-- ------------------------------------------------------------------------
-- Seed data: CUSTOMER, VALUATION_SESSION and CONDITION_FINDING
-- Illustrative example sessions from the project documentation (Sections
-- 5.2 and 5.7), so the tables have related rows to show. Session 1's range
-- (R142,000-R151,000) is quoted from the Section 5.7 sample dialogue;
-- sessions 2-4 only have a single value in the source doc, so their range
-- is +/-8% around it, matching the accuracy target in Section 2.3. The
-- documentation names only "Polo", "Corolla", "Ranger" and "i20", so each
-- is linked to a common variant of that model in VEHICLE_MODEL.
-- ------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.CUSTOMER ON;
SET IDENTITY_INSERT dbo.CUSTOMER OFF;
GO

SET IDENTITY_INSERT dbo.VALUATION_SESSION ON;
     EstimatedValue, EstimatedValueLow, EstimatedValueHigh, ValuationModelUsed,
     OutsideTrainingYears, DesiredCashDeposit, CreatedAt)
SELECT s.SessionID, s.CustomerID, v.ModelID, s.VehicleYear, s.Mileage,
       s.EstimatedValue, s.EstimatedValueLow, s.EstimatedValueHigh, N'XGBoost',
       CASE WHEN s.VehicleYear < 2018 THEN 1 ELSE 0 END, s.DesiredCashDeposit,
       DATEADD(DAY, -s.DaysAgo, SYSDATETIME())
FROM (VALUES
    -- Session 1: doc Section 5.7 illustrative dialogue (VW Polo)
    (1, 1, N'Volkswagen', N'Polo Hatch 1.0TSI 70kW Life',  2019,  85000, 146500.00, 142000.00, 151000.00, NULL,     6),
    -- Session 2: doc Section 5.2 illustrative table, row 2 (Toyota Corolla)
    (2, 2, N'Toyota',     N'Corolla Quest 1.8 Plus Auto',   2017, 132000, 168000.00, 154560.00, 181440.00, NULL,     4),
    -- Session 3: doc Section 5.2 illustrative table, row 3 (Ford Ranger)
    (3, 3, N'Ford',       N'Ranger 2.2TDCi Double Cab Hi-Rider XL', 2020, 60000, 312000.00, 287040.00, 336960.00, 50000.00, 2),
    -- Session 4: doc Section 5.2 illustrative table, row 4 (Hyundai i20)
    (4, 4, N'Hyundai',    N'i20 1.2 Motion',                2016, 150000,  89000.00,  81880.00,  96120.00, NULL,     0)
) AS s (SessionID, CustomerID, Make, Model, VehicleYear, Mileage,
        EstimatedValue, EstimatedValueLow, EstimatedValueHigh, DesiredCashDeposit, DaysAgo)
JOIN dbo.VEHICLE_MODEL v ON v.Make = s.Make AND v.Model = s.Model;
SET IDENTITY_INSERT dbo.VALUATION_SESSION OFF;
GO

-- Session 1's condition findings: the two things the customer mentions in
-- the doc Section 5.7 sample dialogue. Confidence is what the trained intent
-- classifier actually outputs for these exact sentences.
 N'small, about the size of a golf ball', N'NLP', 0.899, 0, NULL),
(1, N'aftermarket_mods', N'Aftermarket wheels, fitted by a reputable tyre shop',
 N'wheels; reputable installer', N'NLP', 0.773, 0, NULL);
GO

