UNION ALL SELECT 'VEHICLE_MODEL', COUNT(*) FROM dbo.VEHICLE_MODEL
UNION ALL SELECT 'VEHICLE', COUNT(*) FROM dbo.VEHICLE
UNION ALL SELECT 'VALUATION_SESSION', COUNT(*) FROM dbo.VALUATION_SESSION
UNION ALL SELECT 'CONDITION_CATEGORY', COUNT(*) FROM dbo.CONDITION_CATEGORY
UNION ALL SELECT 'CONDITION_FINDING', COUNT(*) FROM dbo.CONDITION_FINDING;
GO
